import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { chmodSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { recordedInvocations } from "../src/execute";
import { createFixture, wardLauncher, type Fixture } from "../src/fixture";
import { writeRecordingWrapper } from "../src/live";
import { cleanupOwnedProcesses, run, SYSTEM_PATH } from "../src/process";

// Executes the hook file and wrapper generated by the real `ward integrate copilot
// --guard-approved-specs` against the Copilot CLI 1.0.98 hooks reference
// (docs.github.com/en/copilot/reference/copilot-cli-reference/cli-hooks-reference):
// - .github/hooks/*.json holds {version: 1, hooks}; each handler needs bash, powershell, command or
//   exec; env values are strings; a matcher compiles as ^(?:PATTERN)$ over the tool name, and an
//   invalid one skips the handler.
// - PascalCase events (PreToolUse, PostToolUse, Stop) send the VS Code compatible snake_case
//   payload: hook_event_name, tool_name, tool_input, stop_hook_active.
// - preToolUse denies with permissionDecision; exit 2 or another failure denies too.
// - postToolUse exit 2 is only a warning; findings reach the agent as additionalContext.
// - Stop continues the turn with decision block; sessionEnd output is ignored.
// The real Ward answers behind a recording wrapper.

const EVENTS = [
  "sessionStart",
  "sessionEnd",
  "userPromptSubmitted",
  "userPromptTransformed",
  "preToolUse",
  "postToolUse",
  "postToolUseFailure",
  "permissionRequest",
  "preCompact",
  "notification",
  "agentStop",
  "subagentStart",
  "subagentStop",
  "errorOccurred",
  "SessionStart",
  "SessionEnd",
  "UserPromptSubmit",
  "PreToolUse",
  "PostToolUse",
  "PreCompact",
  "Notification",
  "Stop",
  "SubagentStart",
  "SubagentStop",
];

/** Applies the documented Copilot hook file rules; returns the reasons a handler would be lost. */
function copilotRejects(json: string): string[] {
  let config: any;
  try {
    config = JSON.parse(json);
  } catch {
    return ["not JSON"];
  }
  const errors: string[] = [];
  if (config.version !== 1) errors.push("version is not 1");
  for (const [event, handlers] of Object.entries(config.hooks ?? {})) {
    if (!EVENTS.includes(event)) errors.push(`unknown event ${event}`);
    (handlers as any[]).forEach((handler, index) => {
      const where = `${event}[${index}]`;
      if ((handler.type ?? "command") !== "command") errors.push(`${where} is not a command`);
      if (![handler.bash, handler.command, handler.powershell, handler.exec].some((c) => typeof c === "string")) {
        errors.push(`${where} has no command`);
      }
      if (handler.matcher !== undefined) {
        try {
          new RegExp(`^(?:${handler.matcher})$`);
        } catch {
          errors.push(`${where} matcher is invalid`);
        }
      }
      if (Object.values(handler.env ?? {}).some((v) => typeof v !== "string")) errors.push(`${where} env is not strings`);
      if (handler.timeoutSec !== undefined && typeof handler.timeoutSec !== "number") errors.push(`${where} timeoutSec`);
    });
  }
  return errors;
}

let fixture: Fixture;
let unguarded: Fixture;
let config: any;
let log: string;
let bin: string;

beforeAll(async () => {
  const ward = wardLauncher(process.env)!;
  fixture = await createFixture({ harness: "copilot", guard: true, ward });
  unguarded = await createFixture({ harness: "copilot", guard: false, ward });
  config = JSON.parse(readFileSync(join(fixture.root, ".github/hooks/ward.json"), "utf8"));
  bin = join(dirname(fixture.root), "ward-bin");
  log = join(dirname(fixture.root), "ward-log");
  writeRecordingWrapper(bin, log, ward);
  for (const f of [fixture, unguarded]) {
    await run(["/usr/bin/git", "init", "-q"], { cwd: f.root, env: f.env, timeoutMs: 30_000 });
    mkdirSync(join(f.root, "src/main/java"), { recursive: true });
  }
  mkdirSync(join(fixture.root, "openspec/specs/auth"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/specs/auth/spec.md"), "# Auth\n");
  mkdirSync(join(fixture.root, "openspec/changes/add-x"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/changes/add-x/tasks.md"), "- [ ] 1.1\n");
  writeFileSync(join(fixture.root, "openspec-stub.sh"), '#!/bin/sh\nif [ -f SPEC_FAIL ]; then echo "add-x: missing scenario"; exit 1; fi\n');
  chmodSync(join(fixture.root, "openspec-stub.sh"), 0o755);
  const toml = join(fixture.root, "ward.toml");
  writeFileSync(toml, `${readFileSync(toml, "utf8")}\n[quality-gates.openspec]\nenabled = true\ncommand = ["./openspec-stub.sh"]\n`);
});

afterAll(() => {
  fixture?.cleanup();
  unguarded?.cleanup();
  cleanupOwnedProcesses();
});

const handlers = (event: string, tool?: string, cfg = config) =>
  ((cfg.hooks[event] ?? []) as any[]).filter(
    (h) => tool === undefined || h.matcher === undefined || new RegExp(`^(?:${h.matcher})$`).test(tool),
  );

/** Runs a handler like Copilot: its bash command through the shell, with its env and the event on stdin. */
async function launch(f: Fixture, handler: any, payload: unknown, cwd = f.root) {
  const before = recordedInvocations(log).length;
  const env = { ...f.env, ...handler.env, PATH: `${bin}:${SYSTEM_PATH}` };
  const stdin = typeof payload === "string" ? payload : JSON.stringify({ session_id: "s", timestamp: "t", cwd, ...(payload as object) });
  const result = await run(["/bin/sh", "-c", handler.bash], { cwd, env, stdin, timeoutMs: 60_000 });
  return { result, invocations: recordedInvocations(log).slice(before) };
}

const tool = (event: string, name: string, input: Record<string, unknown>, cwd?: string) =>
  launch(fixture, handlers(event, name)[0], { hook_event_name: event, tool_name: name, tool_input: input }, cwd);

describe("generated hook file against the Copilot CLI 1.0.98 hooks reference", () => {
  test("Copilot accepts every generated handler", () => {
    expect(copilotRejects(readFileSync(join(fixture.root, ".github/hooks/ward.json"), "utf8"))).toEqual([]);
  });

  test("negative control: the legacy hook file loses its handlers", () => {
    expect(copilotRejects(readFileSync(join(import.meta.dir, "legacy-hooks.json.txt"), "utf8"))).toEqual([
      "version is not 1",
      "preToolUse[0] has no command",
    ]);
  });

  test("the guard runs before shell and edit tools; checks run after edits and at Stop", () => {
    for (const name of ["bash", "edit", "create"]) expect(handlers("PreToolUse", name).length).toBe(1);
    expect(handlers("PreToolUse", "view").length).toBe(0);
    expect(handlers("PreToolUse", "bash_extra").length).toBe(0);
    expect(handlers("PostToolUse", "edit").length).toBe(1);
    expect(handlers("PostToolUse", "create").length).toBe(1);
    expect(handlers("PostToolUse", "bash").length).toBe(0);
    expect(handlers("Stop").length).toBe(1);
  });

  test("checks get more time than Copilot's 30 second default, since a timeout fails open", () => {
    expect(handlers("PostToolUse", "edit")[0].timeoutSec).toBeGreaterThanOrEqual(300);
    expect(handlers("Stop")[0].timeoutSec).toBeGreaterThanOrEqual(300);
  });

  test("the ownership marker is in each handler's env", () => {
    for (const event of Object.keys(config.hooks)) {
      for (const h of config.hooks[event]) expect(h.env.WARD_OWNERSHIP).toContain("ward-owned: copilot-native-hooks v1");
    }
  });
});

describe("hook execution", () => {
  test("the guard denies an absolute edit path inside approved specs, from a subdirectory", async () => {
    const { result, invocations } = await tool(
      "PreToolUse",
      "edit",
      { path: join(fixture.root, "openspec/specs/auth/spec.md"), old_str: "# Auth", new_str: "# Changed" },
      join(fixture.root, "src/main/java"),
    );
    expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "copilot", "--guard-approved-specs", "--event-stdin"]]);
    expect(invocations[0].cwd.endsWith("/project")).toBe(true);
    const decision = JSON.parse(result.stdout);
    expect(decision.permissionDecision).toBe("deny");
    expect(decision.permissionDecisionReason).toContain("openspec/specs/auth/spec.md");
  });

  test("the guard allows creating a file in an active change", async () => {
    const { result } = await tool("PreToolUse", "create", { path: join(fixture.root, "openspec/changes/add-x/design.md"), file_text: "x" });
    expect([result.exitCode, result.stdout.trim()]).toEqual([0, ""]);
  });

  test("the guard denies a protected shell command and passes a harmless one", async () => {
    const denied = await tool("PreToolUse", "bash", { command: "rm openspec/specs/auth/spec.md" });
    expect(JSON.parse(denied.result.stdout).permissionDecision).toBe("deny");
    const allowed = await tool("PreToolUse", "bash", { command: "ls src" });
    expect([allowed.result.exitCode, allowed.result.stdout.trim()]).toEqual([0, ""]);
  });

  test("uninspectable input is denied", async () => {
    const { result } = await launch(fixture, handlers("PreToolUse", "bash")[0], "{not json");
    expect(JSON.parse(result.stdout).permissionDecision).toBe("deny");
  });

  test("a failing check after an edit reaches the agent as additionalContext", async () => {
    writeFileSync(join(fixture.root, "FAIL"), "");
    try {
      const { result, invocations } = await tool("PostToolUse", "edit", { path: join(fixture.root, "src/main/java/A.java") });
      expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "copilot", "--event-stdin"]]);
      expect(result.exitCode).toBe(0);
      expect(JSON.parse(result.stdout).additionalContext).toContain("Ward quality findings");
    } finally {
      rmSync(join(fixture.root, "FAIL"), { force: true });
    }
  });

  test("a clean edit is silent", async () => {
    const { result } = await tool("PostToolUse", "edit", { path: join(fixture.root, "src/main/java/A.java") });
    expect([result.exitCode, result.stdout.trim()]).toEqual([0, ""]);
  });

  test("Stop findings continue the turn once with decision block, then only report", async () => {
    writeFileSync(join(fixture.root, "SPEC_FAIL"), "");
    try {
      const stop = (active: boolean) =>
        launch(fixture, handlers("Stop")[0], { hook_event_name: "Stop", stop_reason: "end_turn", stop_hook_active: active });
      const first = await stop(false);
      expect(first.result.exitCode).toBe(0);
      const decision = JSON.parse(first.result.stdout);
      expect(decision.decision).toBe("block");
      expect(decision.reason).toContain("missing scenario");
      const second = await stop(true);
      expect([second.result.exitCode, second.result.stdout.trim()]).toEqual([0, ""]);
      expect(second.result.stderr).toContain("missing scenario");
    } finally {
      rmSync(join(fixture.root, "SPEC_FAIL"), { force: true });
    }
  });

  test("with the guard disabled, the pre phase allows without running Ward", async () => {
    const unguardedConfig = JSON.parse(readFileSync(join(unguarded.root, ".github/hooks/ward.json"), "utf8"));
    const { result, invocations } = await launch(unguarded, handlers("PreToolUse", "bash", unguardedConfig)[0], {
      hook_event_name: "PreToolUse",
      tool_name: "bash",
      tool_input: { command: "rm openspec/specs/auth/spec.md" },
    });
    expect([result.exitCode, result.stdout.trim(), invocations.length]).toEqual([0, "", 0]);
  });
});
